params.command:
$ErrorActionPreference='Continue'
$r='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\HeavenBridge\launch-observation-port-probe'
git -C $r fetch origin --prune | Out-Null
if(Test-Path $wt){git -C $r worktree remove --force $wt 2>$null | Out-Null}
git -C $r worktree prune | Out-Null
git -C $r worktree add --detach $wt origin/main | Out-Host
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
try{
  git -C $wt cherry-pick --no-commit 44f86d94fa4f5b9ddf878b706ab23e28be56ac6f 2>&1 | Out-Host
  $cp=$LASTEXITCODE
  $status=@(git -C $wt status --short)
  $unmerged=@(git -C $wt diff --name-only --diff-filter=U)
  $changed=@(git -C $wt diff --name-only)
  [pscustomobject]@{main=(git -C $wt rev-parse HEAD).Trim();cherry_pick_exit=$cp;unmerged=$unmerged;changed=$changed;status=$status}|ConvertTo-Json -Depth 5
} finally {
  git -C $wt cherry-pick --abort 2>$null | Out-Null
  git -C $r worktree remove --force $wt 2>$null | Out-Null
  git -C $r worktree prune | Out-Null
}
